import java.lang.ref.WeakReference;

public class Main {
    public static void main(String[] args) {
        // 1. Strong Reference (Default)
        Person strong = new Person("Strong");

        // 2. Weak Reference
        // If GC happens, 'weak' points to null instantly
        WeakReference<Person> weak = new WeakReference<>(new Person("Weak"));

        System.out.println("Before GC: " + weak.get());

        System.gc(); // Hint GC (For Demo)

        // 'Strong' is still there. 'Weak' is gone.
        System.out.println("After GC: " + weak.get());
    }
}
